package com.gratilo.user.domain;
import jakarta.persistence.*; import lombok.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="pools",schema="user_mgmt") @Getter @Setter @NoArgsConstructor
public class PoolEntity { @Id private UUID id; @Column(nullable=false,length=16) private String status="ACTIVE"; @Column(name="deleted_at") private OffsetDateTime deletedAt; @Column(name="dissolution_started_at") private OffsetDateTime dissolutionStartedAt; public boolean isAvailable(){return "ACTIVE".equals(status)&&deletedAt==null;} public boolean isDeleted(){return "DELETED".equals(status)||deletedAt!=null;} @Column(name="owner_id",nullable=false) private UUID ownerId; @Column(nullable=false,length=120) private String name; @Column(name="profile_image",columnDefinition="TEXT") private String profileImage; @Column(name="public_path",unique=true,length=120) private String publicPath; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; }
